import {
  deleteHistory,
  getHistoryList,
  HistoryListItem,
} from '@/services/Api/agentic';
import { useGlobalStore } from '@/store';
import { message } from 'antd';
import { useEffect, useState } from 'react';
import DataItem from './DataItem';
import Footer from './Footer';
import Header from './Header';
import styles from './index.module.less';

const NewHistory: React.FC = () => {
  const {
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();
  const { sideCarPort } = sideCarIDEInfo;
  const [page, setPage] = useState({
    pageNum: 1,
    pageSize: 10,
  });
  const [hasMore, setHasMore] = useState<boolean>(false);
  const [loading, setLoading] = useState<boolean>(false);
  const [historyList, setHistoryList] = useState<Array<HistoryListItem>>([]);
  const [filterType, setFilterType] = useState<'all' | 'chat' | 'agent'>('all');

  // 获取历史分页列表
  const fetchHistoryList = async (
    page: { pageNum: number; pageSize: number },
    isReset: boolean = false,
  ) => {
    const { success, data: res } = await getHistoryList(
      {
        ...page,
        repoRef: sideCarIDEInfo?.rootDirectory
          ? `local/${sideCarIDEInfo.rootDirectory}`
          : '',
      },
      `http://localhost:${sideCarPort}`,
    );

    if (success) {
      setLoading(false);
      if (res?.data?.length) {
        // 根据版本和过滤类型过滤数据
        let filteredData = res.data;
        // 根据选择的过滤类型进行过滤
        if (filterType !== 'all') {
          filteredData = filteredData.filter((item: HistoryListItem) =>
            filterType === 'agent'
              ? item.type === 'agent'
              : item.type !== 'agent',
          );
        }

        setHistoryList((prev) => {
          return isReset ? [...filteredData] : [...filteredData, ...prev];
        });
        setHasMore(res.hasMore || false);
      } else {
        setHistoryList([]);
        setHasMore(false);
      }
    }
  };

  useEffect(() => {
    fetchHistoryList(page, true);
  }, [page, filterType]);

  // 加载更多
  const getMore = async () => {
    if (loading) return;
    setLoading(true);
    setPage({
      pageNum: page.pageNum + 1,
      pageSize: page.pageSize,
    });
  };

  // 删除单条
  const deleteOne = async (chatId: string) => {
    const { success } = await deleteHistory(
      { ids: [chatId] },
      `http://localhost:${sideCarPort}`,
    );
    if (success) {
      message.success('删除成功！');
      fetchHistoryList(
        {
          pageNum: 1,
          pageSize: page.pageNum * page.pageSize,
        },
        true,
      );
    }
  };

  // 批量删除
  const deleteAll = async () => {
    if (historyList.length === 0) {
      message.warning('没有可删除的记录');
      return;
    }

    const idsToDelete = historyList.slice(0, 10).map((item) => item.chatId);
    const { success } = await deleteHistory(
      { ids: idsToDelete },
      `http://localhost:${sideCarPort}`,
    );
    if (success) {
      message.success('批量删除成功！');
      fetchHistoryList(
        {
          pageNum: 1,
          pageSize: page.pageNum * page.pageSize,
        },
        true,
      );
    }
  };

  // 处理过滤类型变化
  const handleFilterChange = (type: 'all' | 'chat' | 'agent') => {
    setFilterType(type);
    setPage({
      pageNum: 1,
      pageSize: 10,
    });
  };

  return (
    <div className={styles.history}>
      <Header
        onDelete={deleteAll}
        filterType={filterType}
        onFilterChange={handleFilterChange}
      />
      <div className={styles.history_list}>
        {historyList.map((item) => {
          return (
            <DataItem key={item.chatId} data={item} onDelete={deleteOne} />
          );
        })}
      </div>
      <Footer getMore={getMore} hasMore={hasMore} loading={loading} />
    </div>
  );
};
export default NewHistory;
