import { useGlobalStore } from '@/store';
import { HistoryOutlined } from '@ant-design/icons';
import { history } from '@umijs/max';
import { Radio, Tooltip } from 'antd';
import styles from './index.module.less';

interface HeaderProps {
  onDelete: () => void;
  filterType: 'all' | 'chat' | 'agent';
  onFilterChange: (type: 'all' | 'chat' | 'agent') => void;
}

const Header: React.FC<HeaderProps> = ({
  onDelete,
  filterType,
  onFilterChange,
}) => {
  const {
    pluginConfig: { mode },
  } = useGlobalStore();

  const onExitClick = () => {
    history.push(mode === 'agent' ? '/chat' : '/oldChat');
  };

  return (
    <div className={styles.history_header}>
      <div>
        <HistoryOutlined />
        <span style={{ marginLeft: 5 }}>会话历史</span>
      </div>
      <div className={`${styles.right}`}>
        {
          <Radio.Group
            value={filterType}
            onChange={(e) => onFilterChange(e.target.value)}
            size="small"
          >
            <Radio value="all">全部</Radio>
            <Radio value="chat">Chat</Radio>
            <Radio value="agent">Agent</Radio>
          </Radio.Group>
        }
        <Tooltip title="删除 10 条历史记录" placement="left">
          <span onClick={onDelete}>批量删除</span>
        </Tooltip>
        <span onClick={onExitClick}>返回</span>
      </div>
    </div>
  );
};
export default Header;
