import { ReactComponent as DeleteSVG } from '@/assets/common/delete.svg';
import { HistoryListItem } from '@/services/Api/agentic';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useChatStore, useGlobalStore } from '@/store';
import { history } from '@umijs/max';
import { Tag, Tooltip } from 'antd';
import styles from './index.module.less';

interface DataItemProps {
  data: HistoryListItem;
  onDelete: (chatId: string) => void;
}

const getTagColorByType = (type: string) => {
  return type === 'chat' ? 'green' : 'blue';
};

const DataItem: React.FC<DataItemProps> = ({ data, onDelete }) => {
  const { setChatList } = useChatStore();
  const { setPluginConfig, pluginConfig } = useGlobalStore();
  const { chatId, type, createTime } = data;

  const getDetail = async (chatId: string, type: 'chat' | 'agent') => {
    // 先设置配置
    setPluginConfig({
      ...pluginConfig,
      mode: type === 'chat' ? 'chat' : 'agent',
    });

    jsBridgePostMessage({
      command: 'setPluginConfig',
      data: {
        mode: type === 'chat' ? 'chat' : 'agent',
      },
    });

    // 如果是chat类型，直接替换当前会话
    if (type === 'chat') {
      const newChatItem = {
        chatId,
        chatType: 'history' as const,
        openTime: new Date().getTime(),
      };
      setChatList([newChatItem]);
      history.push('/oldChat');
    } else {
      // 如果是 agent 类型，直接跳转到 agent 页面，让页面自己处理会话切换
      history.push(`/chat?chatId=${chatId}`);
    }
  };

  return (
    <li key={chatId} onClick={() => getDetail(chatId, type)}>
      <div
        className={styles.history_list_close}
        onClick={(e) => {
          e.stopPropagation();
          onDelete(chatId);
        }}
      >
        <Tooltip placement="top" title="点击将删除当前历史记录">
          <DeleteSVG />
        </Tooltip>
      </div>
      <p className={styles.title}>
        <Tag color={getTagColorByType(data.type)} className={styles.tag}>
          {type === 'chat' ? 'chat' : 'agent'}
        </Tag>
        {createTime}
      </p>
      <p>{data.content}</p>
    </li>
  );
};
export default DataItem;
