import { LoadingOutlined } from '@ant-design/icons';
import styles from './index.module.less';

interface FooterProps {
  loading: boolean;
  hasMore: boolean;
  getMore: () => void;
}

const Footer: React.FC<FooterProps> = ({ loading, hasMore, getMore }) => {
  return loading ? (
    <div className={styles.history_loading}>
      <LoadingOutlined />
      加载中...
    </div>
  ) : (
    <div className={styles.history_page}>
      {hasMore ? <span onClick={getMore}>查看更多</span> : '没有更多啦~'}
    </div>
  );
};

export default Footer;
